-- Named connector instances and the organisation's chosen systems (adjustments I1, D81; T79).
-- Generated by drizzle-kit, then edited by hand: the backfills and the order around them.
-- One transaction (the migrator runs pending migrations in one):
--   0. `integrations` and `tenants` stop forcing row-level security on their owner for the length
--      of this transaction, and `integrations` stops touching `updated_at`: on a database whose
--      owner does not bypass RLS (Supabase's `postgres`) the owner would otherwise see no row, and
--      naming an instance should leave every other column as it was. Both come back at the end;
--      ALTER TABLE holds an ACCESS EXCLUSIVE lock until commit, so nobody sees the table meanwhile;
--   1. `integrations.name`, nullable first; every existing instance is named "<kind> – <host>";
--      then NOT NULL and the length check, and a BEFORE INSERT trigger that gives a row inserted
--      without a name that same default (core's `createIntegration` always names an instance;
--      seeds and older tests insert rows without one);
--   2. `tenants.settings` with its default, then every organisation that already has an instance
--      gets `{"systems": [<its kinds>]}`, so Settings › Integrations keeps showing it;
--   3. back to normal.
-- No new privilege: the app role already UPDATEs both tables.

-- 0. Owner access for the backfills; undone at step 3.
ALTER TABLE "restro"."integrations" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."integrations" DISABLE TRIGGER "integrations_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."tenants" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint

-- 1. The instance name.
ALTER TABLE "restro"."integrations" ADD COLUMN "name" text;--> statement-breakpoint
UPDATE "restro"."integrations" SET "name" = "kind" || ' – ' || "host" WHERE "name" IS NULL;--> statement-breakpoint
DO $$
DECLARE
  unnamed bigint;
BEGIN
  SELECT count(*) INTO unnamed FROM restro.integrations WHERE name IS NULL;
  IF unnamed > 0 THEN
    RAISE EXCEPTION '0018_integration_instances: % instances are still unnamed; the migration owner must be able to update restro.integrations (superuser, BYPASSRLS, or the table owner)', unnamed;
  END IF;
END
$$;--> statement-breakpoint
ALTER TABLE "restro"."integrations" ALTER COLUMN "name" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."integrations" ADD CONSTRAINT "integrations_name_length" CHECK (char_length("restro"."integrations"."name") between 1 and 80 and "restro"."integrations"."name" = btrim("restro"."integrations"."name"));--> statement-breakpoint
CREATE FUNCTION restro.integrations_default_name()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  IF NEW.name IS NULL THEN
    NEW.name := left(NEW.kind || ' – ' || NEW.host, 80);
  END IF;
  RETURN NEW;
END
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION restro.integrations_default_name() FROM PUBLIC;--> statement-breakpoint
CREATE TRIGGER integrations_default_name BEFORE INSERT ON restro.integrations
  FOR EACH ROW EXECUTE FUNCTION restro.integrations_default_name();--> statement-breakpoint

-- 2. The organisation's chosen systems.
ALTER TABLE "restro"."tenants" ADD COLUMN "settings" jsonb DEFAULT '{}'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."tenants" ADD CONSTRAINT "tenants_settings_object" CHECK (jsonb_typeof("restro"."tenants"."settings") = 'object');--> statement-breakpoint
UPDATE "restro"."tenants" t
SET "settings" = t."settings" || jsonb_build_object('systems', chosen.kinds)
FROM (
  SELECT i."tenant_id", jsonb_agg(DISTINCT i."kind") AS kinds
  FROM "restro"."integrations" i
  GROUP BY i."tenant_id"
) AS chosen
WHERE chosen."tenant_id" = t."id";--> statement-breakpoint

-- 3. Back to normal.
ALTER TABLE "restro"."integrations" ENABLE TRIGGER "integrations_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."integrations" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."tenants" FORCE ROW LEVEL SECURITY;
